<script>
      (function () {
        function initCarousel() {
          var carousel = document.getElementById("testimonials-carousel");
          var prev = document.getElementById("tc-prev");
          var next = document.getElementById("tc-next");
          
          function smoothScroll(el, target, duration) {
            var start = el.scrollLeft;
            var change = target - start;
            var startTime = null;
            function easeInOut(t) { return t < 0.5 ? 2*t*t : -1+(4-2*t)*t; }
            function step(ts) {
              if (!startTime) startTime = ts;
              var p = Math.min((ts - startTime) / duration, 1);
              el.scrollLeft = start + change * easeInOut(p);
              if (p < 1) requestAnimationFrame(step);
            }
            requestAnimationFrame(step);
          }

          if (carousel && prev && next) {
            prev.addEventListener("click", function () { smoothScroll(carousel, carousel.scrollLeft - 360, 300); });
            next.addEventListener("click", function () { smoothScroll(carousel, carousel.scrollLeft + 360, 300); });

            var cards = carousel.querySelectorAll(".carousel-card");
            cards.forEach(function (card) {
              var textEl = card.querySelector("p.line-clamp-5");
              if (textEl && textEl.textContent.trim().length <= 220) {
                var btn = textEl.nextElementSibling;
                if (btn) btn.style.display = "none";
              }
            });
          }
        }

        if (document.readyState === "loading") {
          document.addEventListener("DOMContentLoaded", initCarousel);
        } else {
          initCarousel();
        }
      })();
    </script>
